  "intro": "太和殿坐落在紫禁城中轴线的核心，是北京最负盛名的一景。三层汉白玉台基层层托起金瓦重檐，殿前开阔的广场曾见证帝王登基与颁诏盛典。晴日蓝天之下金顶灼灼生辉，檐角脊兽静守六百年光阴，庄严得让人不由得放轻脚步。",
