  "rarity": "SR",
  "intro": "德寿宫在市中心，石造殿的西洋柱廊与传统的殿宇挨在一起，是朝鲜王朝末年的影子。秋天的银杏把宫道铺成金色，墙外的车流声隐约传来。傍晚宫门亮灯，石墙上的影子被拉得很长，散步的人慢慢走过。",
